package com.vishnu.hotelassistant.service;
import com.vishnu.hotelassistant.dto.*; import com.vishnu.hotelassistant.entity.*; import com.vishnu.hotelassistant.repository.AppUserRepository; import com.vishnu.hotelassistant.security.JwtService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import org.springframework.http.HttpStatus;
@Service public class AuthService { private final AppUserRepository repo; private final PasswordEncoder enc; private final JwtService jwt; public AuthService(AppUserRepository repo,PasswordEncoder enc,JwtService jwt){this.repo=repo;this.enc=enc;this.jwt=jwt;}
 public AuthResponse register(RegisterRequest r){if(repo.existsByEmail(r.email()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already registered"); AppUser u=AppUser.builder().name(r.name()).email(r.email().toLowerCase()).password(enc.encode(r.password())).role(Role.USER).build(); repo.save(u); return new AuthResponse(jwt.generate(u.getEmail()),u.getEmail(),u.getRole().name());}
 public AuthResponse login(LoginRequest r){AppUser u=repo.findByEmail(r.email().toLowerCase()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password")); if(!enc.matches(r.password(),u.getPassword()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password"); return new AuthResponse(jwt.generate(u.getEmail()),u.getEmail(),u.getRole().name());}
}
